import re


VERSION_CORE = r"""
(?:0|[1-9]\d*)\.
(?:0|[1-9]\d*)\.
(?:0|[1-9]\d*)
(?:-
  (?P<pre>
    (?:0|[1-9]\d*|[0-9A-Za-z-]*[A-Za-z-][0-9A-Za-z-]*)
    (?:\.
      (?:0|[1-9]\d*|[0-9A-Za-z-]*[A-Za-z-][0-9A-Za-z-]*)
    )*
  )
)?
"""

VERSION_RE = re.compile(r"^" + VERSION_CORE + r"$", re.VERBOSE)

COMPARATOR_RE = re.compile(
    r"^(?P<op>>=|<=|>|<|=|\^|~)?" + VERSION_CORE + r"$",
    re.VERBOSE,
)


def parse_version(s):
    m = VERSION_RE.fullmatch(s)
    if not m:
        raise ValueError("invalid version")

    major = int(m.group(1))
    minor = int(m.group(2))
    patch = int(m.group(3))
    pre = m.group("pre")

    if pre is None:
        prerelease = None
    else:
        prerelease = tuple(
            int(part) if part.isdigit() else part
            for part in pre.split(".")
        )

    return (major, minor, patch, prerelease)


def cmp_versions(a, b):
    for i in range(3):
        if a[i] != b[i]:
            return -1 if a[i] < b[i] else 1

    a_pre = a[3]
    b_pre = b[3]

    if a_pre is None and b_pre is None:
        return 0
    if a_pre is None:
        return 1
    if b_pre is None:
        return -1

    for x, y in zip(a_pre, b_pre):
        if isinstance(x, int) and isinstance(y, int):
            if x != y:
                return -1 if x < y else 1
        elif isinstance(x, int):
            return -1
        elif isinstance(y, int):
            return 1
        else:
            if x != y:
                return -1 if x < y else 1

    if len(a_pre) != len(b_pre):
        return -1 if len(a_pre) < len(b_pre) else 1

    return 0


def upper_caret(v):
    major, minor, patch, _ = v
    if major > 0:
        return (major + 1, 0, 0, None)
    if minor > 0:
        return (0, minor + 1, 0, None)
    return (0, 0, patch + 1, None)


def upper_tilde(v):
    major, minor, _, _ = v
    return (major, minor + 1, 0, None)


def comparator_matches(version, op, target):
    c = cmp_versions(version, target)

    if op == "" or op == "=":
        return c == 0
    if op == ">":
        return c > 0
    if op == ">=":
        return c >= 0
    if op == "<":
        return c < 0
    if op == "<=":
        return c <= 0
    if op == "^":
        return c >= 0 and cmp_versions(version, upper_caret(target)) < 0
    if op == "~":
        return c >= 0 and cmp_versions(version, upper_tilde(target)) < 0

    return False


def parse_range(rng):
    raw_sets = rng.split("||")
    if not raw_sets:
        raise ValueError("invalid range")

    parsed_sets = []
    for raw_set in raw_sets:
        raw_set = raw_set.strip()
        if not raw_set:
            raise ValueError("invalid range")

        comparators = raw_set.split()
        if not comparators:
            raise ValueError("invalid range")

        parsed_comparators = []
        for comp in comparators:
            m = COMPARATOR_RE.fullmatch(comp)
            if not m:
                raise ValueError("invalid comparator")

            op = m.group("op") or ""
            target = parse_version(m.group("version"))
            parsed_comparators.append((op, target))

        parsed_sets.append(parsed_comparators)

    return parsed_sets


def satisfies(version, rng):
    v = parse_version(version)
    sets = parse_range(rng)

    for comparators in sets:
        if not all(comparator_matches(v, op, target) for op, target in comparators):
            continue

        if v[3] is not None:
            if not any(
                target[3] is not None and target[:3] == v[:3]
                for _, target in comparators
            ):
                continue

        return True

    return False
