from datetime import datetime, timedelta
from bisect import bisect_left


def _parse_int(s):
    if not s:
        raise ValueError
    for ch in s:
        if ch not in "0123456789":
            raise ValueError
    return int(s)


def _parse_field(field, lo, hi):
    if field == "*":
        return set(range(lo, hi + 1)), False

    values = set()
    items = field.split(",")

    for item in items:
        if item == "":
            raise ValueError

        if "/" in item:
            parts = item.split("/")
            if len(parts) != 2:
                raise ValueError
            base, step_s = parts
            step = _parse_int(step_s)
            if step < 1:
                raise ValueError
            slash_present = True
        else:
            base = item
            step = 1
            slash_present = False

        if base == "*":
            start, end = lo, hi
        elif "-" in base:
            parts = base.split("-")
            if len(parts) != 2:
                raise ValueError
            start = _parse_int(parts[0])
            end = _parse_int(parts[1])
            if start > end:
                raise ValueError
        else:
            start = _parse_int(base)
            end = hi if slash_present else start

        if start < lo or end > hi:
            raise ValueError

        values.update(range(start, end + 1, step))

    return values, True


def _cron_dow(dt):
    return (dt.weekday() + 1) % 7


def _day_matches(dt, dom_set, dow_set, dom_restricted, dow_restricted):
    dom_ok = dt.day in dom_set
    dow_ok = _cron_dow(dt) in dow_set

    if dom_restricted and dow_restricted:
        return dom_ok or dow_ok
    return dom_ok and dow_ok


def next_fire(expr, after):
    fields = expr.split()
    if len(fields) != 5:
        raise ValueError

    minute_set, _ = _parse_field(fields[0], 0, 59)
    hour_set, _ = _parse_field(fields[1], 0, 23)
    dom_set, dom_restricted = _parse_field(fields[2], 1, 31)
    month_set, _ = _parse_field(fields[3], 1, 12)
    dow_set, dow_restricted = _parse_field(fields[4], 0, 7)

    if 7 in dow_set:
        dow_set.add(0)
        dow_set.discard(7)

    minutes = sorted(minute_set)
    hours = sorted(hour_set)

    candidate = after.replace(second=0, microsecond=0)
    if candidate <= after:
        candidate += timedelta(minutes=1)

    limit = after + timedelta(days=3000)

    while candidate <= limit:
        if candidate.month not in month_set:
            if candidate.month == 12:
                candidate = datetime(candidate.year + 1, 1, 1, 0, 0)
            else:
                candidate = datetime(candidate.year, candidate.month + 1, 1, 0, 0)
            continue

        if not _day_matches(candidate, dom_set, dow_set, dom_restricted, dow_restricted):
            candidate = candidate.replace(hour=0, minute=0) + timedelta(days=1)
            continue

        for h in hours:
            if h < candidate.hour:
                continue

            start_minute = candidate.minute if h == candidate.hour else 0
            idx = bisect_left(minutes, start_minute)

            if idx < len(minutes):
                return datetime(candidate.year, candidate.month, candidate.day, h, minutes[idx])

        candidate = candidate.replace(hour=0, minute=0) + timedelta(days=1)

    raise ValueError
