import copy


class PatchError(ValueError):
    pass


def apply_patch(doc, ops):
    """Apply a JSON Patch (RFC 6902 subset) to `doc` and return the resulting NEW document.

    `doc` and `ops` must never be modified, and the result must share no mutable object (dict/list) with either.
    The patch is all-or-nothing: on any error, raise PatchError.

    `ops` is a list of dicts. Each has "op" (one of add, remove, replace, move, copy, test) and "path";
    add/replace/test also need "value" (which may be None); move/copy also need "from". Missing keys are errors.

    Paths are JSON Pointers: "" is the whole document; otherwise "/" followed by "/"-separated tokens in which
    "~1" stands for "/" and "~0" for "~" ("~01" is the key "~1"). A "~" not followed by 0 or 1 is an error.
    A token addressing a list must be a base-10 index without leading zeros ("0" is fine). "-" means "past the
    end of the list" and is only allowed as the final token of an add (or of the target of move/copy).

    add:     object -> set the member (replacing any existing value); list -> insert BEFORE the index
             (index == len appends, index > len is an error). Adding at "" replaces the whole document.
             The parent container must exist.
    remove:  the target must exist. Removing "" is an error.
    replace: the target must exist. Replacing "" replaces the whole document.
    move:    remove the value at "from", then add it at "path". It is an error if "path" lies strictly inside
             "from" (a proper descendant). from == path is a no-op, but "from" must still exist.
    copy:    add a deep copy of the value at "from" at "path".
    test:    the target must exist and equal "value". Equality is JSON equality: numbers by value (1 == 1.0),
             booleans are never equal to numbers, objects by keys and values, lists elementwise.
    """
    try:
        return _apply_patch(doc, ops)
    except PatchError:
        raise
    except Exception:
        raise PatchError


def _apply_patch(doc, ops):
    if not isinstance(ops, list):
        raise PatchError

    result = copy.deepcopy(doc)

    for op in ops:
        if not isinstance(op, dict):
            raise PatchError

        if "op" not in op or "path" not in op:
            raise PatchError

        kind = op["op"]
        path = op["path"]

        if kind not in {"add", "remove", "replace", "move", "copy", "test"}:
            raise PatchError

        if kind in {"add", "replace", "test"}:
            if "value" not in op:
                raise PatchError
            value = op["value"]
        elif kind in {"move", "copy"}:
            if "from" not in op:
                raise PatchError
            src = op["from"]

        if kind == "add":
            result = _add(result, _parse_pointer(path), copy.deepcopy(value))
        elif kind == "remove":
            _remove(result, _parse_pointer(path))
        elif kind == "replace":
            result = _replace(result, _parse_pointer(path), copy.deepcopy(value))
        elif kind == "move":
            result = _move(result, _parse_pointer(src), _parse_pointer(path))
        elif kind == "copy":
            result = _copy(result, _parse_pointer(src), _parse_pointer(path))
        elif kind == "test":
            _test(result, _parse_pointer(path), value)

    return result


def _parse_pointer(path):
    if not isinstance(path, str):
        raise PatchError

    if path == "":
        return []

    if not path.startswith("/"):
        raise PatchError

    raw_tokens = path[1:].split("/")
    tokens = []

    for raw in raw_tokens:
        token = []
        i = 0
        while i < len(raw):
            ch = raw[i]
            if ch == "~":
                if i + 1 >= len(raw):
                    raise PatchError
                nxt = raw[i + 1]
                if nxt == "0":
                    token.append("~")
                elif nxt == "1":
                    token.append("/")
                else:
                    raise PatchError
                i += 2
            else:
                token.append(ch)
                i += 1
        tokens.append("".join(token))

    return tokens


def _is_list_index(token):
    if token == "0":
        return True
    if not token:
        return False
    if token[0] not in "123456789":
        return False
    return all(ch in "0123456789" for ch in token)


def _get_value(container, tokens):
    cur = container
    for token in tokens:
        if isinstance(cur, list):
            if not _is_list_index(token):
                raise PatchError
            idx = int(token)
            if idx >= len(cur):
                raise PatchError
            cur = cur[idx]
        elif isinstance(cur, dict):
            if token not in cur:
                raise PatchError
            cur = cur[token]
        else:
            raise PatchError
    return cur


def _add(container, tokens, value):
    if not tokens:
        return value

    parent = _get_value(container, tokens[:-1])
    token = tokens[-1]

    if isinstance(parent, list):
        if token == "-":
            parent.append(value)
        elif _is_list_index(token):
            idx = int(token)
            if idx > len(parent):
                raise PatchError
            parent.insert(idx, value)
        else:
            raise PatchError
    elif isinstance(parent, dict):
        parent[token] = value
    else:
        raise PatchError

    return container


def _remove(container, tokens):
    if not tokens:
        raise PatchError

    parent = _get_value(container, tokens[:-1])
    token = tokens[-1]

    if isinstance(parent, list):
        if not _is_list_index(token):
            raise PatchError
        idx = int(token)
        if idx >= len(parent):
            raise PatchError
        return parent.pop(idx)
    elif isinstance(parent, dict):
        if token not in parent:
            raise PatchError
        return parent.pop(token)
    else:
        raise PatchError


def _replace(container, tokens, value):
    if not tokens:
        return value

    parent = _get_value(container, tokens[:-1])
    token = tokens[-1]

    if isinstance(parent, list):
        if not _is_list_index(token):
            raise PatchError
        idx = int(token)
        if idx >= len(parent):
            raise PatchError
        parent[idx] = value
    elif isinstance(parent, dict):
        if token not in parent:
            raise PatchError
        parent[token] = value
    else:
        raise PatchError

    return container


def _move(container, src_tokens, dst_tokens):
    if src_tokens == dst_tokens:
        _get_value(container, src_tokens)
        return container

    if len(dst_tokens) > len(src_tokens) and dst_tokens[:len(src_tokens)] == src_tokens:
        raise PatchError

    value = _remove(container, src_tokens)
    return _add(container, dst_tokens, value)


def _copy(container, src_tokens, dst_tokens):
    value = _get_value(container, src_tokens)
    return _add(container, dst_tokens, copy.deepcopy(value))


def _test(container, tokens, value):
    target = _get_value(container, tokens)
    if not _json_equal(target, value):
        raise PatchError


def _json_equal(a, b):
    if isinstance(a, bool) or isinstance(b, bool):
        return isinstance(a, bool) and isinstance(b, bool) and a == b

    if isinstance(a, (int, float)) and isinstance(b, (int, float)):
        return a == b

    if isinstance(a, dict) and isinstance(b, dict):
        if a.keys() != b.keys():
            return False
        return all(_json_equal(a[k], b[k]) for k in a)

    if isinstance(a, list) and isinstance(b, list):
        if len(a) != len(b):
            return False
        return all(_json_equal(x, y) for x, y in zip(a, b))

    return a == b
