import heapq


class CycleError(Exception):
    def __init__(self, cycle):
        super().__init__("dependency cycle: " + " -> ".join(cycle))
        self.cycle = cycle


def build_order(deps):
    """`deps` maps each target (str) to an iterable of targets it depends on (duplicates allowed). Targets that only
    appear as dependencies are leaves. Return a list of ALL targets in which every target comes after all of its
    dependencies. Whenever several targets are ready, the lexicographically smallest is placed first, so the
    order is unique.

    If the graph has a cycle (including a target depending on itself), raise CycleError(cycle) where `cycle`
    lists the targets on the cycle: it starts with the lexicographically smallest target ON the cycle, each element
    depends on the next one, and it ends by repeating the first element (e.g. ["a", "b", "a"], or ["x", "x"]).
    Targets that merely lead into a cycle are not part of it. Inputs with cycles contain exactly one cycle.
    `deps` must not be modified.
    """
    graph = {}
    nodes = set()

    for target, dependencies in deps.items():
        nodes.add(target)
        graph.setdefault(target, set())
        for dep in dependencies:
            nodes.add(dep)
            graph.setdefault(target, set()).add(dep)
            graph.setdefault(dep, set())

    for node in nodes:
        graph.setdefault(node, set())

    color = {node: 0 for node in nodes}

    for start in sorted(nodes):
        if color[start] != 0:
            continue

        stack = [start]
        pos = {start: 0}
        color[start] = 1
        iters = [iter(sorted(graph[start]))]

        while stack:
            u = stack[-1]
            try:
                v = next(iters[-1])
            except StopIteration:
                color[u] = 2
                del pos[u]
                stack.pop()
                iters.pop()
                continue

            if color[v] == 0:
                color[v] = 1
                pos[v] = len(stack)
                stack.append(v)
                iters.append(iter(sorted(graph[v])))
            elif color[v] == 1:
                cycle_nodes = stack[pos[v]:]
                smallest = min(cycle_nodes)
                idx = cycle_nodes.index(smallest)
                rotated = cycle_nodes[idx:] + cycle_nodes[:idx]
                raise CycleError(rotated + [rotated[0]])

    indegree = {node: 0 for node in nodes}
    dependents = {node: set() for node in nodes}

    for target, dependencies in graph.items():
        for dep in dependencies:
            indegree[target] += 1
            dependents[dep].add(target)

    heap = [node for node in nodes if indegree[node] == 0]
    heapq.heapify(heap)

    order = []
    while heap:
        node = heapq.heappop(heap)
        order.append(node)
        for dependent in dependents[node]:
            indegree[dependent] -= 1
            if indegree[dependent] == 0:
                heapq.heappush(heap, dependent)

    return order
