import sqlite3
from decimal import Decimal, ROUND_HALF_UP


def init_v1(conn):
    conn.executescript("""
        CREATE TABLE customers (id INTEGER PRIMARY KEY, name TEXT NOT NULL);
        CREATE TABLE orders (id INTEGER PRIMARY KEY, customer_id INTEGER REFERENCES customers(id),
                             amount REAL NOT NULL, legacy_flag INTEGER);
        CREATE INDEX idx_orders_customer ON orders(customer_id);
        CREATE TABLE order_items (id INTEGER PRIMARY KEY, order_id INTEGER NOT NULL REFERENCES orders(id) ON DELETE CASCADE,
                                  sku TEXT NOT NULL);
        CREATE TABLE schema_version (version INTEGER);
        INSERT INTO schema_version VALUES (1);
    """)


def version(conn):
    return conn.execute("SELECT version FROM schema_version").fetchone()[0]


def _amount_to_cents(amount):
    d = Decimal(repr(float(amount))) * 100
    return int(d.to_integral_value(rounding=ROUND_HALF_UP))


def migrate(conn):
    if version(conn) == 2:
        return

    orders_data = conn.execute("SELECT id, customer_id, amount FROM orders").fetchall()
    order_items_data = conn.execute("SELECT id, order_id, sku FROM order_items").fetchall()

    conn.execute(
        "CREATE TABLE orders_new (id INTEGER PRIMARY KEY, "
        "customer_id INTEGER REFERENCES customers(id), "
        "amount_cents INTEGER NOT NULL)"
    )

    for order_id, customer_id, amount in orders_data:
        conn.execute(
            "INSERT INTO orders_new VALUES (?, ?, ?)",
            (order_id, customer_id, _amount_to_cents(amount)),
        )

    conn.execute("DROP TABLE order_items")
    conn.execute(
        "CREATE TABLE order_items (id INTEGER PRIMARY KEY, "
        "order_id INTEGER NOT NULL REFERENCES orders_new(id) ON DELETE CASCADE, "
        "sku TEXT NOT NULL)"
    )

    for item_id, order_id, sku in order_items_data:
        conn.execute("INSERT INTO order_items VALUES (?, ?, ?)", (item_id, order_id, sku))

    conn.execute("DROP TABLE orders")
    conn.execute("CREATE INDEX idx_orders_customer ON orders_new(customer_id)")
    conn.execute("ALTER TABLE orders_new RENAME TO orders")
    conn.execute("UPDATE schema_version VALUES (2)")
