def glob_match(pattern, path):
    r"""Return True if the "/"-separated relative `path` matches `pattern` (case-sensitive, whole path).

    Pattern syntax:
    - `?` matches exactly one character other than "/".
    - `*` matches zero or more characters other than "/".
    - `[...]` matches one character other than "/" that is in the set; `[!...]` one that is NOT in the set.
      The set holds literal characters and ranges `a-z`. A `]` right after `[` or `[!` is a literal member, and a
      `-` first or last in the set is literal. Backslash has no special meaning inside a set.
      An unterminated `[` raises ValueError.
    - `\x` (backslash then any character) matches x literally. A trailing lone backslash raises ValueError.
    - A pattern segment (text between unescaped "/" outside sets) that is exactly `**` matches zero or more whole
      path segments. Elsewhere `**` is just two `*`.
    - Any other character matches itself.
    Matching must stay fast for patterns with many `*` or `**` (no exponential backtracking).
    """
    def parse_pattern(p):
        segments = []
        current = []
        i = 0
        n = len(p)

        def parse_set():
            nonlocal i
            # i is at '['
            j = i + 1
            negate = False
            if j < n and p[j] == "!":
                negate = True
                j += 1

            search_start = j
            if j < n and p[j] == "]":
                search_start = j + 1

            close = p.find("]", search_start)
            if close == -1:
                raise ValueError("unterminated [ in pattern")

            content = p[j:close]
            i = close + 1

            members = []
            k = 0
            m = len(content)
            while k < m:
                if k == 0 and content[k] == "-":
                    members.append(("-", "-"))
                    k += 1
                elif k == m - 1 and content[k] == "-":
                    members.append(("-", "-"))
                    k += 1
                elif k + 2 < m and content[k + 1] == "-":
                    members.append((content[k], content[k + 2]))
                    k += 3
                else:
                    members.append((content[k], content[k]))
                    k += 1

            def match_char(c):
                if c == "/":
                    return False
                inside = False
                for lo, hi in members:
                    if lo <= c <= hi:
                        inside = True
                        break
                return inside if not negate else not inside

            return match_char

        while i < n:
            c = p[i]
            if c == "\\":
                if i + 1 >= n:
                    raise ValueError("trailing backslash in pattern")
                current.append(("literal", p[i + 1]))
                i += 2
            elif c == "/":
                segments.append(current)
                current = []
                i += 1
            elif c == "[":
                current.append(("set", parse_set()))
            elif c == "*":
                current.append(("star", None))
                i += 1
            elif c == "?":
                current.append(("any", None))
                i += 1
            else:
                current.append(("literal", c))
                i += 1

        segments.append(current)
        return segments

    def match_segment(tokens, s):
        dp = [True] + [False] * len(s)
        for kind, value in tokens:
            ndp = [False] * (len(s) + 1)
            if kind == "literal":
                for j in range(1, len(s) + 1):
                    ndp[j] = dp[j - 1] and s[j - 1] == value
            elif kind == "any":
                for j in range(1, len(s) + 1):
                    ndp[j] = dp[j - 1] and s[j - 1] != "/"
            elif kind == "set":
                for j in range(1, len(s) + 1):
                    ndp[j] = dp[j - 1] and value(s[j - 1])
            elif kind == "star":
                ndp[0] = dp[0]
                for j in range(1, len(s) + 1):
                    ndp[j] = dp[j] or (ndp[j - 1] and s[j - 1] != "/")
            dp = ndp
        return dp[-1]

    pattern_segments = parse_pattern(pattern)
    path_segments = path.split("/") if path != "" else []

    dp = [False] * (len(path_segments) + 1)
    dp[0] = True

    for seg in pattern_segments:
        ndp = [False] * (len(path_segments) + 1)
        if len(seg) == 2 and seg[0] == ("star", None) and seg[1] == ("star", None):
            reachable = False
            for j in range(len(path_segments) + 1):
                reachable = reachable or dp[j]
                ndp[j] = reachable
        else:
            for j in range(len(path_segments)):
                if dp[j] and match_segment(seg, path_segments[j]):
                    ndp[j + 1] = True
        dp = ndp

    return dp[len(path_segments)]
