            if len(path_tokens) > len(from_tokens) and path_tokens[:len(from_tokens)] == from_tokens:
                raise PatchError

            moved = remove_at(result, from_tokens)
            result = add_at(result, path_tokens, moved)

        elif kind == "copy":
            source = get_value(result, from_tokens)
            result = add_at(result, path_tokens, copy.deepcopy(source))

    return result


def parse_pointer(path):
    if not isinstance(path, str):
        raise PatchError

    if path == "":
        return []

    if path[0] != "/":
        raise PatchError

    raw_tokens = path[1:].split("/")
    tokens = []

    for raw in raw_tokens:
        token = []
        i = 0
        while i < len(raw):
            c = raw[i]
            if c == "~":
                if i + 1 >= len(raw):
                    raise PatchError
                nxt = raw[i + 1]
                if nxt == "0":
                    token.append("~")
                elif nxt == "1":
                    token.append("/")
                else:
                    raise PatchError
                i += 2
            else:
                token.append(c)
                i += 1
        tokens.append("".join(token))

    return tokens


def parse_list_index(token, allow_dash=False):
    if allow_dash and token == "-":
        return "-"

    if not token:
        return None

    if token[0] == "0" and len(token) > 1:
        return None

    if not all("0" <= c <= "9" for c in token):
        return None

    return int(token)


def get_value(root, tokens):
    cur = root
    for token in tokens:
        if isinstance(cur, dict):
            if token not in cur:
                raise PatchError
            cur = cur[token]
        elif isinstance(cur, list):
            idx = parse_list_index(token, allow_dash=False)
            if idx is None or idx >= len(cur):
                raise PatchError
            cur = cur[idx]
        else:
            raise PatchError
    return cur


def add_at(root, tokens, value):
    if tokens == []:
        return value

    parent_tokens = tokens[:-1]
    last = tokens[-1]
    parent = get_value(root, parent_tokens)

    if isinstance(parent, dict):
        parent[last] = value
    elif isinstance(parent, list):
        idx = parse_list_index(last, allow_dash=True)
        if idx == "-":
            parent.append(value)
        elif idx is None or idx > len(parent):
            raise PatchError
        else:
            parent.insert(idx, value)
    else:
        raise PatchError

    return root


def remove_at(root, tokens):
    if tokens == []:
        raise PatchError

    parent_tokens = tokens[:-1]
    last = tokens[-1]
    parent = get_value(root, parent_tokens)

    if isinstance(parent, dict):
        if last not in parent:
            raise PatchError
        value = parent[last]
        del parent[last]
        return value

    if isinstance(parent, list):
        idx = parse_list_index(last, allow_dash=False)
        if idx is None or idx >= len(parent):
            raise PatchError
        value = parent[idx]
        del parent[idx]
        return value

    raise PatchError


def replace_at(root, tokens, value):
    if tokens == []:
        return value

    parent_tokens = tokens[:-1]
    last = tokens[-1]
    parent = get_value(root, parent_tokens)

    if isinstance(parent, dict):
        if last not in parent:
            raise PatchError
        parent[last] = value
    elif isinstance(parent, list):
        idx = parse_list_index(last, allow_dash=False)
        if idx is None or idx >= len(parent):
            raise PatchError
        parent[idx] = value
    else:
        raise PatchError

    return root


def json_equal(a, b):
    if isinstance(a, bool) or isinstance(b, bool):
        return isinstance(a, bool) and isinstance(b, bool) and a == b

    if isinstance(a, (int, float)) and isinstance(b, (int, float)):
        return a == b

    if isinstance(a, dict) and isinstance(b, dict):
        if len(a) != len(b):
            return False
        for k in a:
            if k not in b or not json_equal(a[k], b[k]):
                return False
        return True

    if isinstance(a, list) and isinstance(b, list):
        if len(a) != len(b):
            return False
        return all(json_equal(x, y) for x, y in zip(a, b))

    return a == b
