        return "0" <= ch <= "9"

    def is_prerelease_char(ch):
        return (
            is_ascii_digit(ch)
            or ("a" <= ch <= "z")
            or ("A" <= ch <= "Z")
            or ch == "-"
        )

    def parse_core_number(text):
        if not text:
            return None
        for ch in text:
            if not is_ascii_digit(ch):
                return None
        if len(text) > 1 and text[0] == "0":
            return None
        return int(text)

    def parse_prerelease_identifier(text):
        if not text:
            return None
        for ch in text:
            if not is_prerelease_char(ch):
                return None
        if all(is_ascii_digit(ch) for ch in text):
            if len(text) > 1 and text[0] == "0":
                return None
        return text

    def parse_version(text):
        if not isinstance(text, str):
            raise ValueError

        if "+" in text:
            raise ValueError

        if "-" in text:
            core_text, prerelease_text = text.split("-", 1)
        else:
            core_text, prerelease_text = text, None

        core_parts = core_text.split(".")
        if len(core_parts) != 3:
            raise ValueError

        parsed_core = []
        for part in core_parts:
            value = parse_core_number(part)
            if value is None:
                raise ValueError
            parsed_core.append(value)

        prerelease = None
        if prerelease_text is not None:
            identifiers = prerelease_text.split(".")
            parsed_prerelease = []
            for identifier in identifiers:
                parsed_identifier = parse_prerelease_identifier(identifier)
                if parsed_identifier is None:
                    raise ValueError
                parsed_prerelease.append(parsed_identifier)
            prerelease = tuple(parsed_prerelease)

        return (parsed_core[0], parsed_core[1], parsed_core[2], prerelease)

    def compare_prerelease_identifier(left, right):
        left_numeric = all(is_ascii_digit(ch) for ch in left)
        right_numeric = all(is_ascii_digit(ch) for ch in right)

        if left_numeric and right_numeric:
            left_value = int(left)
            right_value = int(right)
            if left_value < right_value:
                return -1
            if left_value > right_value:
                return 1
            return 0

        if left_numeric:
            return -1
        if right_numeric:
