            version_text = text[2:]
        elif text.startswith(">"):
            operator = ">"
            version_text = text[1:]
        elif text.startswith("<"):
            operator = "<"
            version_text = text[1:]
        elif text.startswith("="):
            operator = "="
            version_text = text[1:]
        elif text.startswith("^"):
            operator = "^"
            version_text = text[1:]
        elif text.startswith("~"):
            operator = "~"
            version_text = text[1:]
        else:
            operator = "="
            version_text = text

        if not version_text:
            raise ValueError

