        for raw_set in raw_sets:
            stripped_set = raw_set.strip()
            if not stripped_set:
                raise ValueError

            comparator_texts = stripped_set.split()
            if not comparator_texts:
                raise ValueError

            parsed_comparators = []
            for comparator_text in comparator_texts:
