        if minor > 0:
            return (0, minor + 1, 0, None)
        return (0, 0, patch + 1, None)

    def tilde_upper_bound(target):
        major, minor, patch, _ = target
        return (major, minor + 1, 0, None)

    def comparator_matches(version, comparator):
        operator, target = comparator
        comparison = compare_versions(version, target)

        if operator == "=":
            return comparison == 0
        if operator == ">":
            return comparison > 0
        if operator == ">=":
            return comparison >= 0
        if operator == "<":
            return comparison < 0
        if operator == "<=":
            return comparison <= 0
        if operator == "^":
            upper = caret_upper_bound(target)
            return comparison >= 0 and compare_versions(version, upper) < 0
        if operator == "~":
            upper = tilde_upper_bound(target)
            return comparison >= 0 and compare_versions(version, upper) < 0

        return False

