def _unescape_token(raw):
    out = []
    i = 0
    while i < len(raw):
        c = raw[i]
        if c == "~":
            if i + 1 >= len(raw):
                raise PatchError
            nxt = raw[i + 1]
            if nxt == "0":
                out.append("~")
            elif nxt == "1":
                out.append("/")
            else:
                raise PatchError
            i += 2
        else:
            out.append(c)
            i += 1
    return "".join(out)


