        if isinstance(cur, dict):
            if token not in cur:
                raise PatchError
            cur = cur[token]
        elif isinstance(cur, list):
            idx = _parse_index(token, allow_dash=False)
            if idx < 0 or idx >= len(cur):
                raise PatchError
            cur = cur[idx]
        else:
            raise PatchError
