def _add(root, tokens, value):
    if not tokens:
        return value

    parent = _navigate_parent(root, tokens[:-1])
    last = tokens[-1]

    if isinstance(parent, dict):
        parent[last] = value
    elif isinstance(parent, list):
        if last == "-":
            parent.append(value)
        else:
            idx = _parse_index(last, allow_dash=False)
            if idx < 0 or idx > len(parent):
                raise PatchError
            parent.insert(idx, value)
    else:
        raise PatchError

    return root


def _remove(root, tokens):
    if not tokens:
        raise PatchError

    parent = _navigate_parent(root, tokens[:-1])
    last = tokens[-1]

    if isinstance(parent, dict):
        if last not in parent:
            raise PatchError
        return parent.pop(last)

    if isinstance(parent, list):
        idx = _parse_index(last, allow_dash=False)
        if idx < 0 or idx >= len(parent):
            raise PatchError
        return parent.pop(idx)

    raise PatchError


def _replace(root, tokens, value):
    if not tokens:
        return value

    parent = _navigate_parent(root, tokens[:-1])
    last = tokens[-1]

    if isinstance(parent, dict):
        if last not in parent:
            raise PatchError
        parent[last] = value
    elif isinstance(parent, list):
        idx = _parse_index(last, allow_dash=False)
        if idx < 0 or idx >= len(parent):
            raise PatchError
        parent[idx] = value
    else:
        raise PatchError

    return root


def _parse_index(token, allow_dash=False):
    if token == "-":
        if allow_dash:
            return -1
        raise PatchError

    if not token:
        raise PatchError

    for ch in token:
        if ch < "0" or ch > "9":
            raise PatchError

    if len(token) > 1 and token[0] == "0":
        raise PatchError

    return int(token)


def _json_equal(a, b):
    if isinstance(a, bool) or isinstance(b, bool):
        return isinstance(a, bool) and isinstance(b, bool) and a == b

    if isinstance(a, dict) and isinstance(b, dict):
        if len(a) != len(b):
            return False
        for k in a:
            if k not in b:
                return False
            if not _json_equal(a[k], b[k]):
                return False
        return True

    if isinstance(a, list) and isinstance(b, list):
        if len(a) != len(b):
            return False
        return all(_json_equal(x, y) for x, y in zip(a, b))

    if isinstance(a, (int, float)) and isinstance(b, (int, float)):
        return a == b

    if isinstance(a, str) and isinstance(b, str):
        return a == b

    if a is None and b is None:
        return True

    return False
