import heapq


class CycleError(Exception):
    def __init__(self, cycle):
        super().__init__("dependency cycle: " + " -> ".join(cycle))
        self.cycle = cycle


def build_order(deps):
    """`deps` maps each target (str) to an iterable of targets it depends on (duplicates allowed). Targets that only
    appear as dependencies are leaves. Return a list of ALL targets in which every target comes after all of its
    dependencies. Whenever several targets are ready, the lexicographically smallest is placed first, so the
    order is unique.

    If the graph has a cycle (including a target depending on itself), raise CycleError(cycle) where `cycle`
    lists the targets on the cycle: it starts with the lexicographically smallest target ON the cycle, each element
    depends on the next one, and it ends by repeating the first element (e.g. ["a", "b", "a"], or ["x", "x"]).
    Targets that merely lead into a cycle are not part of it. Inputs with cycles contain exactly one cycle.
    `deps` must not be modified.
    """
    deps_copy = {}
    nodes = set(deps)

    for target, iterable in deps.items():
        ds = list(iterable)
        deps_copy[target] = ds
        nodes.update(ds)

    if not nodes:
        return []

    dep_sets = {node: set() for node in nodes}
    dependents = {node: set() for node in nodes}

    for target, ds in deps_copy.items():
        for dep in ds:
            if dep not in dep_sets[target]:
                dep_sets[target].add(dep)
                dependents[dep].add(target)

    indegree = {node: len(dep_sets[node]) for node in nodes}
    ready = [node for node in nodes if indegree[node] == 0]
    heapq.heapify(ready)

    order = []
    while ready:
        node = heapq.heappop(ready)
        order.append(node)

        for dependent in dependents[node]:
            indegree[dependent] -= 1
            if indegree[dependent] == 0:
                heapq.heappush(ready, dependent)

    if len(order) == len(nodes):
        return order

    remaining = {node for node in nodes if indegree[node] > 0}
    path = []
    seen = {}
    current = min(remaining)

    while current not in seen:
        seen[current] = len(path)
        path.append(current)

        nexts = dep_sets[current] & remaining
        if not nexts:
            # Should not happen for a remaining node in a finite graph, but keep a safe fallback.
            nexts = dep_sets[current]

        current = min(nexts)

    cycle_nodes = path[seen[current]:]
    start = min(range(len(cycle_nodes)), key=lambda i: cycle_nodes[i])
    cycle = cycle_nodes[start:] + cycle_nodes[:start] + [cycle_nodes[start]]

    raise CycleError(cycle)
