from decimal import Decimal, ROUND_HALF_UP


def init_v1(conn):
    conn.executescript("""
        CREATE TABLE customers (id INTEGER PRIMARY KEY, name TEXT NOT NULL);
        CREATE TABLE orders (id INTEGER PRIMARY KEY, customer_id INTEGER REFERENCES customers(id),
                             amount REAL NOT NULL, legacy_flag INTEGER);
        CREATE INDEX idx_orders_customer ON orders(customer_id);
        CREATE TABLE order_items (id INTEGER PRIMARY KEY, order_id INTEGER NOT NULL REFERENCES orders(id) ON DELETE CASCADE,
                                  sku TEXT NOT NULL);
        CREATE TABLE schema_version (version INTEGER);
        INSERT INTO schema_version VALUES (1);
    """)


def version(conn):
    return conn.execute("SELECT version FROM schema_version").fetchone()[0]


def migrate(conn):
    if version(conn) == 2:
        return

    fk = conn.execute("PRAGMA foreign_keys").fetchone()[0]

    old_orders = conn.execute("SELECT id, customer_id, amount FROM orders").fetchall()
    old_order_items = conn.execute("SELECT id, order_id, sku FROM order_items").fetchall()

    conn.execute("PRAGMA foreign_keys = 0")
    conn.execute("DROP TABLE order_items")
    conn.execute("DROP TABLE orders")

    conn.execute("PRAGMA foreign_keys = 1")
    conn.execute(
        "CREATE TABLE orders (id INTEGER PRIMARY KEY, customer_id INTEGER REFERENCES customers(id), amount_cents INTEGER NOT NULL)"
    )
    conn.execute(
        "CREATE TABLE order_items (id INTEGER PRIMARY KEY, order_id INTEGER NOT NULL REFERENCES orders(id) ON DELETE CASCADE, sku TEXT NOT NULL)"
    )

    for order_id, customer_id, amount in old_orders:
        cents = int((Decimal(repr(float(amount))) * 100).quantize(Decimal("1"), rounding=ROUND_HALF_UP))
        conn.execute("INSERT INTO orders VALUES (?, ?, ?)", (order_id, customer_id, cents))

    for item_id, order_id, sku in old_order_items:
        conn.execute("INSERT INTO order_items VALUES (?, ?, ?)", (item_id, order_id, sku))

    conn.execute("CREATE INDEX idx_orders_customer ON orders(customer_id)")
    conn.execute("UPDATE schema_version SET version = 2")

    conn.execute("PRAGMA foreign_keys = %d" % fk)
