def glob_match(pattern, path):
    """Return True if the "/"-separated relative `path` matches `pattern` (case-sensitive, whole path).

    Pattern syntax:
    - `?` matches exactly one character other than "/".
    - `*` matches zero or more characters other than "/".
    - `[...]` matches one character other than "/" that is in the set; `[!...]` one that is NOT in the set.
      The set holds literal characters and ranges `a-z`. A `]` right after `[` or `[!` is a literal member, and a
      `-` first or last in the set is literal. Backslash has no special meaning inside a set.
      An unterminated `[` raises ValueError.
    - `\x` (backslash then any character) matches x literally. A trailing lone backslash raises ValueError.
    - A pattern segment (text between unescaped "/" outside sets) that is exactly `**` matches zero or more whole
      path segments. Elsewhere `**` is just two `*`.
    - Any other character matches itself.
    Matching must stay fast for patterns with many `*` or `**` (no exponential backtracking).
    """
    def parse_pattern(pattern):
        segments = []
        i = 0
        n = len(pattern)

        while True:
            tokens, i = parse_segment(pattern, i)
            if len(tokens) == 2 and tokens[0] == "*" and tokens[1] == "*":
                segments.append("**")
            else:
                segments.append(tokens)

            if i >= n:
                break

            # i is at an unescaped '/' outside a set.
            i += 1

        return segments

    def parse_segment(pattern, i):
        tokens = []
        n = len(pattern)

        while i < n:
            c = pattern[i]

            if c == "\\":
                if i + 1 >= n:
                    raise ValueError("trailing lone backslash")
                tokens.append(pattern[i + 1])
                i += 2

            elif c == "/":
                break

            elif c == "*":
                tokens.append("*")
                i += 1

            elif c == "?":
                tokens.append("?")
                i += 1

            elif c == "[":
                token, i = parse_set(pattern, i)
                tokens.append(token)

            else:
                tokens.append(c)
                i += 1

        return tokens, i

    def parse_set(pattern, i):
        # pattern[i] == '['
        i += 1
        negate = False

        if i < len(pattern) and pattern[i] == "!":
            negate = True
            i += 1

        intervals = []
        first = True

        while i < len(pattern):
            c = pattern[i]

            if c == "]" and not first:
                i += 1
                return ("class", negate, intervals), i

            first = False

            # A '-' first or last in the set is literal.
            if (
                i + 2 < len(pattern)
                and pattern[i + 1] == "-"
                and pattern[i + 2] != "]"
            ):
                low = c
                high = pattern[i + 2]
                if low <= high:
                    intervals.append((low, high))
                i += 3
            else:
                intervals.append((c, c))
                i += 1

        raise ValueError("unterminated [")

    def class_match(token, ch):
        _, negate, intervals = token

        if ch == "/":
            return False

        in_set = False
        for low, high in intervals:
            if low <= ch <= high:
                in_set = True
                break

        return in_set if not negate else not in_set

    def match_segment(tokens, text):
        n = len(text)
        if n == 0:
            return all(tok == "*" for tok in tokens)

        # Bit j means: the first j characters of text can be matched.
        dp = 1
        limit_mask = (1 << (n + 1)) - 1

        # Precompute bit masks for characters appearing in this text segment.
        char_masks = {}
        for pos, ch in enumerate(text, 1):
            char_masks[ch] = char_masks.get(ch, 0) | (1 << pos)

        class_cache = {}

        for tok in tokens:
            if tok == "*":
                # Star can consume zero or more characters: fill all bits to the right.
                x = dp
                shift = 1
                while shift <= n:
                    x |= x << shift
                    shift <<= 1
                dp = x & limit_mask

            elif tok == "?":
                # Any one character except '/', but text segments never contain '/'.
                dp = (dp << 1) & limit_mask & ~1

            elif isinstance(tok, str):
                dp = (dp << 1) & char_masks.get(tok, 0)

            else:
                key = tok
                mask = class_cache.get(key)
                if mask is None:
                    mask = 0
                    for ch, ch_mask in char_masks.items():
                        if class_match(tok, ch):
                            mask |= ch_mask
                    class_cache[key] = mask

                dp = (dp << 1) & mask

            if dp == 0:
                return False

        return ((dp >> n) & 1) == 1

    pattern_segments = parse_pattern(pattern)
    path_segments = path.split("/")

    dp = [False] * (len(path_segments) + 1)
    dp[0] = True

    for pat_seg in pattern_segments:
        new_dp = [False] * (len(path_segments) + 1)

        if pat_seg == "**":
