from collections import namedtuple
from decimal import Decimal
import re

Event = namedtuple("Event", "id kind account target amount")

_AMOUNT_RE = re.compile(r"\d+(?:\.\d{1,2})?")


def parse_event(raw):
    """Validate a raw event dict and return an Event.

    Required keys: "id" (non-empty str), "kind" ("deposit", "withdraw" or "transfer"), "account" (non-empty str) and
    "amount" (a str of digits, optionally followed by "." and one or two digits, e.g. "5", "0.1", "12.34"; its value
    must be > 0). A transfer also needs "target" (non-empty str, different from "account"); other kinds ignore it.
    Anything else (missing keys, wrong types, "1e2", "1.234", "-5", "0.00", ...) raises ValueError.
    """
    try:
        event_id = raw["id"]
        kind = raw["kind"]
        account = raw["account"]
        amount_raw = raw["amount"]
    except (KeyError, TypeError, IndexError):
        raise ValueError("missing or invalid required key") from None

    if not isinstance(event_id, str) or event_id == "":
        raise ValueError("bad id")
    if not isinstance(kind, str) or kind not in ("deposit", "withdraw", "transfer"):
        raise ValueError("bad kind")
    if not isinstance(account, str) or account == "":
        raise ValueError("bad account")
    if not isinstance(amount_raw, str) or not _AMOUNT_RE.fullmatch(amount_raw):
        raise ValueError("bad amount")

    amount = Decimal(amount_raw)
    if amount <= 0:
        raise ValueError("amount must be positive")

    target = None
    if kind == "transfer":
        try:
            target = raw["target"]
        except (KeyError, TypeError, IndexError):
            raise ValueError("transfer requires target") from None
        if not isinstance(target, str) or target == "" or target == account:
            raise ValueError("bad target")

    return Event(event_id, kind, account, target, amount)
