from events import parse_event
from decimal import Decimal


def _amount_to_cents(amount):
    sign, digits, exponent = amount.as_tuple()
    value = int("".join(str(d) for d in digits))
    if sign:
        value = -value

    if exponent == 0:
        return value * 100
    if exponent == -1:
        return value * 10
    if exponent == -2:
        return value

    raise ValueError("amount has too many decimal places")


class Ledger:
    """In-memory account ledger.

    - balance(acct) returns a decimal.Decimal with exactly two decimal places; unknown accounts have Decimal("0.00").
    - apply(raw) returns True when the event is applied, or False when an event with the same id was already APPLIED
      (it is then ignored).
    - Invalid events (see events.parse_event) and events that would make any balance negative raise ValueError,
      change nothing, and are not remembered: a later event with the same id is processed normally.
    - withdraw and transfer may bring a balance down to exactly zero.
    - A transfer moves the amount from `account` to `target` atomically.
    """

    def __init__(self):
        self._bal = {}
        self._seen = set()

    def balance(self, acct):
        cents = self._bal.get(acct, 0)
        if cents < 0:
            return Decimal(f"-{(-cents) // 100}.{(-cents) % 100:02d}")
        return Decimal(f"{cents // 100}.{cents % 100:02d}")

    def apply(self, raw):
        try:
            raw_id = raw["id"]
        except (KeyError, TypeError, IndexError):
            raw_id = None

        if isinstance(raw_id, str) and raw_id in self._seen:
            return False

        ev = parse_event(raw)
        cents = _amount_to_cents(ev.amount)

        if ev.kind == "deposit":
            self._bal[ev.account] = self._bal.get(ev.account, 0) + cents
        elif ev.kind == "withdraw":
            bal = self._bal.get(ev.account, 0)
            if bal - cents < 0:
                raise ValueError("insufficient funds")
            self._bal[ev.account] = bal - cents
        else:
            source_bal = self._bal.get(ev.account, 0)
            if source_bal - cents < 0:
                raise ValueError("insufficient funds")
            target_bal = self._bal.get(ev.target, 0)
            self._bal[ev.account] = source_bal - cents
            self._bal[ev.target] = target_bal + cents

        self._seen.add(ev.id)
        return True
